import type { CSSObject, Theme } from "@emotion/react";
import type { TabProps } from "./tab.types";
import type { ComponentStyleVariantConfig } from "@types";

import * as RadixTabs from "@radix-ui/react-tabs";
import styled from "@emotion/styled";
import { getStyleSlots, getExcludedDOMProps } from "@system";
import { useMemo } from "react";

// Make sure component name matches its type in the ThemeComponentVariants - using TabBar for existing theme tokens
const componentName = "TabBar";

// Generate child element class names for the component, should match available style slots
export const TabClasses = {
  root: "exp-textura_tab",
  sm: "exp-textura_tab_sm",
  actionButton: "exp-textura_tab_action_button",
  badge: "exp-textura_tab_badge",
  inlineBadge: "exp-textura_tab_inline_badge",
  icon: "exp-textura_tab_icon",
};

const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
  line: {
    root: {
      borderRadius: 0,
      backgroundColor: theme.tab.line.color.background.enabled,
      color: theme.tab.line.color.content.enabled,
      borderBottom: `${theme.toRem(theme.border.width.md)} solid transparent`,
      height: theme.toRem(40),
    },
    hover: {
      backgroundColor: theme.tab.line.color.background.hover,
      color: theme.tab.line.color.content.hover,
      borderBottom: `${theme.toRem(theme.border.width.md)} solid ${theme.tab.line.color.content.hover}`,
    },
    pressed: {
      backgroundColor: theme.tab.line.color.background.pressed,
      color: theme.tab.line.color.content.pressed,
      borderBottom: `${theme.toRem(theme.border.width.md)} solid ${theme.tab.line.color.content.pressed}`,
    },
    selected: {
      backgroundColor: theme.tab.line.color.background.selected,
      color: theme.tab.line.color.content.selected,
      borderBottom: `${theme.toRem(theme.border.width.md)} solid ${theme.tab.line.color.content.selected}`,
    },
    disabled: {
      backgroundColor: theme.tab.line.color.background.disabled,
      color: theme.tab.line.color.content.disabled,
      borderBottom: "none",
    },
  },
  vertical: {
    root: {
      justifyContent: "start",
      width: "100%",
      padding: theme.toRem(theme.spacing[8]),
      height: theme.toRem(32),
      backgroundColor: theme.tab.vertical.color.background.enabled,
      color: theme.tab.vertical.color.content.enabled,
    },
    hover: {
      backgroundColor: theme.tab.vertical.color.background.hover,
      color: theme.tab.vertical.color.content.hover,
    },
    pressed: {
      backgroundColor: theme.tab.vertical.color.background.pressed,
      color: theme.tab.vertical.color.content.pressed,
    },
    selected: {
      backgroundColor: theme.tab.vertical.color.background.selected,
      color: theme.tab.vertical.color.content.selected,
    },
    disabled: {
      backgroundColor: theme.tab.vertical.color.background.disabled,
      color: theme.tab.vertical.color.content.disabled,
    },
    badge: {
      marginInlineStart: "auto",
    },
    inlineBadge: {
      marginInlineStart: "auto",
    },
  },
});

const generateStyles = ({
  theme,
  variant,
  styleSlots: styleSlotsProp,
}: {
  theme: Theme;
  variant: TabProps["variant"];
  styleSlots?: TabProps["styleSlots"];
}): CSSObject => {
  if (!theme?.tab) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<TabProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  return {
    display: "inline-flex",
    alignItems: "center",
    gap: theme.toRem(theme.spacing[8]),
    backgroundColor: "unset",
    position: "relative",
    cursor: "pointer",
    flexWrap: "nowrap",
    justifyContent: "center",
    whiteSpace: "nowrap",
    font: "inherit",
    outline: "none",
    padding: `0 ${theme.toRem(theme.spacing[8])}`,
    color: theme.tab.default.color.content.enabled,
    borderRadius: theme.toRem(theme.border.radius.sm),
    border: "none",
    height: theme.toRem(32),
    ...theme.typography.label.md,

    "&:focus-visible": {
      boxShadow: `0 0 0 2px ${theme.color.border.default}`,
      outline: "none",
    },

    "&:hover:not([data-disabled]):not([data-state='active'])": {
      color: theme.tab.default.color.content.hover,
      backgroundColor: theme.tab.default.color.background.hover,
      [`.${TabClasses.icon}`]: {
        color: theme.color.content.iconStrong,
        ...styleSlots?.iconHover,
      },
      ...styleSlots?.hover,
    },

    "&:active:not([data-disabled])": {
      backgroundColor: theme.tab.default.color.background.pressed,
      color: theme.tab.default.color.content.pressed,
      [`.${TabClasses.icon}`]: {
        color: theme.color.content.iconStrong,
        ...styleSlots?.iconPressed,
      },
      ...styleSlots?.pressed,
    },

    // selected
    [`&[data-state="active"]`]: {
      cursor: "default",
      backgroundColor: theme.tab.default.color.background.selected,
      color: theme.tab.default.color.content.selected,
      [`.${TabClasses.icon}`]: {
        color: theme.color.content.iconStrong,
        ...styleSlots?.iconSelected,
      },
      ...styleSlots?.selected,
    },

    // disabled
    [`&[data-disabled]`]: {
      backgroundColor: theme.tab.default.color.background.disabled,
      color: theme.tab.default.color.content.disabled,
      cursor: "default",
      [`.${TabClasses.icon}`]: {
        color: theme.color.content.iconWeak,
        ...styleSlots?.iconDisabled,
      },
      ...styleSlots?.disabled,
    },

    [`&.${TabClasses.sm}`]: {
      height: theme.toRem(24),
      padding: `0 ${theme.toRem(theme.spacing[8])}`,
      ...theme.typography.label.sm,
      ...styleSlots?.sm,
    },

    [`.${TabClasses.icon}`]: {
      display: "flex",
      alignItems: "center",
      color: theme.color.content.icon,
      fontSize: theme.toRem(16),
      ...styleSlots?.icon,
    },

    [`.${TabClasses.badge}`]: {
      marginInlineStart: `calc(${theme.toRem(theme.spacing[4])} * -1)`,
      ...styleSlots?.badge,
    },

    [`.${TabClasses.inlineBadge}`]: {
      ...styleSlots?.inlineBadge,
    },

    [`.${TabClasses.inlineBadge} + .${TabClasses.badge}, .${TabClasses.badge} + .${TabClasses.inlineBadge}`]:
      {
        marginInlineStart: `calc(${theme.toRem(theme.spacing[4])} * -1)`,
      },

    [`.${TabClasses.actionButton}`]: {
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      color: "inherit",
      marginInlineEnd: theme.toRem(-6),
      borderRadius: theme.toRem(theme.border.radius.sm),
      "> svg": {
        width: theme.toRem(12),
        height: theme.toRem(12),
        ...styleSlots?.actionButtonIcon,
      },
      ...styleSlots?.actionButton,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

export const StyledTab = styled(RadixTabs.Trigger, {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<{
  currentTheme: Theme;
  variant: TabProps["variant"];
  styleSlots?: TabProps["styleSlots"];
}>((props) => generateStyles(props));
